// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this) && newOwner != address(c));
        address initialOwner = c.owner();
        vm.assume(newOwner != initialOwner);
        Attacker attacker = new Attacker(c);
        vm.prank(initialOwner);
        c.transferOwnership(address(attacker));
        address origOwnerAfterAttack = c.owner();
        assertTrue(origOwnerAfterAttack == address(attacker));
    }
}

contract Attacker {
    Owned public target;
    constructor(Owned _target) { target = _target; }
    fallback() external payable {
        target.transferOwnership(address(this));
    }
}
